[CmdletBinding()]
param(
    [Parameter(Position = 0)]
    [string]$Command = 'help',

    [Parameter(Position = 1, ValueFromRemainingArguments)]
    [string[]]$CliArguments = @()
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
Import-Module (Join-Path $PSScriptRoot 'TaskForge.Core.psm1') -Force -WarningAction SilentlyContinue

try {
    $repoRoot = Split-Path -Parent $PSScriptRoot
    $defaultDataFile = Join-Path $repoRoot 'data/tasks.json'
    $defaultConfigFile = Join-Path $repoRoot 'config/taskforge.config.json'
    $bannerFile = Join-Path $repoRoot 'assets/config.txt'
    $commandName = $Command.ToLowerInvariant()

    if ($commandName -eq 'config') {
        $parsed = ConvertFrom-ConfigArguments -Arguments $CliArguments
        $configOptions = $parsed.Options
        $positionals = @($parsed.Positionals)

        foreach ($name in $configOptions.Keys) {
            if ($name -notin @('config-file', 'json')) {
                throw "Unknown option: --$name"
            }
        }

        $configFile = if ($configOptions.Contains('config-file')) {
            Get-RequiredOption -Options $configOptions -Name 'config-file'
        }
        else {
            $defaultConfigFile
        }
        $configJson = $configOptions.Contains('json')

        if ($positionals.Count -eq 0) {
            throw 'config requires an action: set, get, or list.'
        }
        $action = $positionals[0].ToLowerInvariant()

        switch ($action) {
            'set' {
                if ($positionals.Count -ne 3) {
                    throw 'config set requires exactly a key and a value.'
                }
                $key = $positionals[1]
                $value = $positionals[2]
                if ($key -notin @('dataFile', 'defaultJson')) {
                    throw "Unknown config key: $key"
                }

                $config = Read-ConfigStore -Path $configFile
                $stored = if ($key -eq 'defaultJson') {
                    ConvertTo-ConfigBoolean -Value $value
                }
                else {
                    [string]$value
                }
                $config[$key] = $stored
                Write-ConfigStore -Path $configFile -Config $config

                if ($configJson) {
                    Write-TaskForgeOutput -Value ([pscustomobject]@{ $key = $stored }) -AsJson $true
                }
                else {
                    "Set $key = $(Format-ConfigValue $stored)"
                }
            }
            'get' {
                if ($positionals.Count -ne 2) {
                    throw 'config get requires exactly a key.'
                }
                $key = $positionals[1]
                if ($key -notin @('dataFile', 'defaultJson')) {
                    throw "Unknown config key: $key"
                }

                $config = Read-ConfigStore -Path $configFile
                $value = if ($config.Contains($key)) { $config[$key] } else { $null }

                if ($configJson) {
                    ConvertTo-Json -InputObject $value -Depth 8 -Compress
                }
                else {
                    Format-ConfigValue $value
                }
            }
            'list' {
                if ($positionals.Count -ne 1) {
                    throw 'config list does not accept extra arguments.'
                }
                $config = Read-ConfigStore -Path $configFile

                if ($configJson) {
                    $payload = [ordered]@{
                        dataFile = if ($config.Contains('dataFile')) { [string]$config['dataFile'] } else { $null }
                        defaultJson = if ($config.Contains('defaultJson')) { [bool]$config['defaultJson'] } else { $null }
                    }
                    Write-TaskForgeOutput -Value ([pscustomobject]$payload) -AsJson $true
                }
                else {
                    if (-not (Test-Path -LiteralPath $bannerFile)) {
                        throw "Config banner asset is missing: $bannerFile"
                    }
                    $lines = [System.Collections.Generic.List[string]]::new()
                    foreach ($bannerLine in (Get-Content -LiteralPath $bannerFile)) {
                        $lines.Add($bannerLine)
                    }
                    $dataFileDisplay = if ($config.Contains('dataFile')) { [string]$config['dataFile'] } else { '(unset)' }
                    $defaultJsonDisplay = if ($config.Contains('defaultJson')) { Format-ConfigValue $config['defaultJson'] } else { '(unset)' }
                    $lines.Add("dataFile = $dataFileDisplay")
                    $lines.Add("defaultJson = $defaultJsonDisplay")
                    $lines.ToArray()
                }
            }
            default {
                throw "Unknown config action: $action"
            }
        }
    }
    else {
        $options = ConvertFrom-TaskForgeArguments -Arguments $CliArguments
        $configFile = if ($options.Contains('config-file')) {
            Get-RequiredOption -Options $options -Name 'config-file'
        }
        else {
            $defaultConfigFile
        }
        $config = Read-ConfigStore -Path $configFile

        $dataFile = if ($options.Contains('data-file')) {
            Get-RequiredOption -Options $options -Name 'data-file'
        }
        elseif ($config.Contains('dataFile')) {
            Resolve-ConfigPath -ConfigFile $configFile -Value ([string]$config['dataFile'])
        }
        else {
            $defaultDataFile
        }
        $asJson = $options.Contains('json') -or ($config.Contains('defaultJson') -and [bool]$config['defaultJson'])

        switch ($commandName) {
            'add' {
                Assert-KnownOptions -Options $options -Allowed @('title', 'description', 'data-file', 'json', 'config-file')
                $title = Get-RequiredOption -Options $options -Name 'title'
                $tasks = @(Read-TaskStore -Path $dataFile)
                $nextId = if ($tasks.Count -eq 0) { 1 } else { 1 + [int](($tasks | Measure-Object -Property id -Maximum).Maximum) }
                $task = [ordered]@{
                    id = $nextId
                    title = $title.Trim()
                    description = if ($options.Contains('description')) { [string]$options['description'] } else { '' }
                    status = 'pending'
                    createdAt = [DateTimeOffset]::UtcNow.ToString('o')
                }
                Write-TaskStore -Path $dataFile -Tasks @($tasks + [pscustomobject]$task)
                if ($asJson) {
                    Write-TaskForgeOutput -Value ([pscustomobject]$task) -AsJson $true
                }
                else {
                    "Added task ${nextId}: $($task.title)"
                }
            }
            'list' {
                Assert-KnownOptions -Options $options -Allowed @('data-file', 'json', 'config-file')
                $tasks = @(Read-TaskStore -Path $dataFile | Sort-Object { [int]$_.id })
                if ($asJson) {
                    Write-TaskForgeOutput -Value $tasks -AsJson $true
                }
                elseif ($tasks.Count -eq 0) {
                    'No tasks.'
                }
                else {
                    $tasks | ForEach-Object { "[{0}] #{1} {2}" -f $_.status, $_.id, $_.title }
                }
            }
            'complete' {
                Assert-KnownOptions -Options $options -Allowed @('id', 'data-file', 'json', 'config-file')
                $idText = Get-RequiredOption -Options $options -Name 'id'
                $id = 0
                if (-not [int]::TryParse($idText, [ref]$id) -or $id -le 0) {
                    throw '--id must be a positive integer.'
                }
                $tasks = @(Read-TaskStore -Path $dataFile)
                $task = $tasks | Where-Object { [int]$_.id -eq $id } | Select-Object -First 1
                if ($null -eq $task) {
                    throw "Task $id was not found."
                }
                $task.status = 'completed'
                Write-TaskStore -Path $dataFile -Tasks $tasks
                if ($asJson) {
                    Write-TaskForgeOutput -Value $task -AsJson $true
                }
                else {
                    "Completed task $id."
                }
            }
            'remove' {
                Assert-KnownOptions -Options $options -Allowed @('id', 'data-file', 'json', 'config-file')
                $idText = Get-RequiredOption -Options $options -Name 'id'
                $id = 0
                if (-not [int]::TryParse($idText, [ref]$id) -or $id -le 0) {
                    throw '--id must be a positive integer.'
                }
                $tasks = @(Read-TaskStore -Path $dataFile)
                $remaining = @($tasks | Where-Object { [int]$_.id -ne $id })
                if ($remaining.Count -eq $tasks.Count) {
                    throw "Task $id was not found."
                }
                Write-TaskStore -Path $dataFile -Tasks $remaining
                $summary = [pscustomobject]@{ removedId = $id }
                if ($asJson) {
                    Write-TaskForgeOutput -Value $summary -AsJson $true
                }
                else {
                    "Removed task $id."
                }
            }
            'help' {
                Assert-KnownOptions -Options $options -Allowed @('config-file')
                @'
TaskForge
  add --title TEXT [--description TEXT] [--data-file PATH] [--json] [--config-file PATH]
  list [--data-file PATH] [--json] [--config-file PATH]
  complete --id ID [--data-file PATH] [--json] [--config-file PATH]
  remove --id ID [--data-file PATH] [--json] [--config-file PATH]
  config set KEY VALUE [--config-file PATH] [--json]
  config get KEY [--config-file PATH] [--json]
  config list [--config-file PATH] [--json]

Config keys: dataFile (path), defaultJson (true|false)
'@
            }
            default {
                throw "Unknown command: $Command"
            }
        }
    }
}
catch {
    [Console]::Error.WriteLine("TaskForge: $($_.Exception.Message)")
    exit 1
}

